import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 2345678;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total_real = sc.nextInt();
        int max_k_value = sc.nextInt();

        double[] prob_real = new double[123];
        double[] prob = new double[123];
        double[] dp_array = new double[MAX_SIZE];
        double[] result_arr = new double[123];
        int[] idx = new int[123];
        int[] bits_count = new int[MAX_SIZE];

        int valid_count = 0;
        for (int i = 0; i < total_real; i++) {
            prob_real[i] = sc.nextDouble();
            if (prob_real[i] > 1e-4) {
                idx[valid_count] = i;
                prob[valid_count] = prob_real[i];
                valid_count++;
            }
        }

        max_k_value = Math.min(max_k_value, valid_count);

        bits_count[0] = 0;
        for (int mask = 1; mask < (1 << valid_count); mask++) {
            bits_count[mask] = bits_count[mask & (mask - 1)] + 1;
        }

        for (int mask = 0; mask < (1 << valid_count); mask++) {
            dp_array[mask] = 0.0;
        }

        for (int i = 0; i < total_real; i++) {
            result_arr[i] = 0.0;
        }

        dp_array[0] = 1.0;

        for (int mask = 0; mask < (1 << valid_count); mask++) {
            if (bits_count[mask] == max_k_value) {
                for (int j = 0; j < valid_count; j++) {
                    if ((mask & (1 << j)) != 0) {
                        result_arr[idx[j]] += dp_array[mask];
                    }
                }
                continue;
            }
            double total_prob = 0;
            for (int j = 0; j < valid_count; j++) {
                if ((mask & (1 << j)) != 0) continue;
                total_prob += prob[j];
            }
            double ratio = total_prob == 0 ? 0 : dp_array[mask] / total_prob;
            for (int j = 0; j < valid_count; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int new_mask = mask | (1 << j);
                dp_array[new_mask] += prob[j] * ratio;
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < total_real; i++) {
            if (i > 0) output.append(" ");
            output.append(String.format("%.17f", result_arr[i]));
        }
        System.out.println(output.toString());
        sc.close();
    }
}
